<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Perfect Maze Discovery — 24 Bots</title>
<style>
  *{box-sizing:border-box}
  body{margin:0;font-family:system-ui,Arial,sans-serif;background:#111;color:#eee;display:flex;flex-direction:column;align-items:center;min-height:100vh;padding:16px}
  h1{font-size:20px;margin:8px 0}
  #hud{display:flex;gap:16px;align-items:center;background:#1e1e1e;border:1px solid #444;border-radius:10px;padding:10px 16px;margin-bottom:12px}
  #hud .pill{background:#000;border:1px solid #555;border-radius:8px;padding:4px 10px;min-width:90px;text-align:center}
  #hud .label{font-size:11px;color:#aaa;text-transform:uppercase;letter-spacing:.08em}
  #hud .val{font-size:18px;font-weight:700}
  #reset{cursor:pointer;background:#2e7d32;color:#fff;border:none;border-radius:8px;padding:10px 18px;font-size:15px;font-weight:700}
  #reset:hover{background:#388e3c}
  #maze{background:#000;border:2px solid #666;border-radius:10px;padding:8px}
  #cv{display:block;background:#fff;border-radius:4px}
  #info{font-size:12px;color:#aaa;margin-top:8px;max-width:640px;text-align:center}
</style>
</head>
<body>
<h1>Maze Discovery — 24 Exploring Bots</h1>
<div id="hud">
  <div class="pill"><div class="label">Completed</div><div class="val" id="completed">0/24</div></div>
  <div class="pill"><div class="label">Timer (ticks)</div><div class="val" id="timer">0</div></div>
  <button id="reset">Reset</button>
</div>
<div id="maze"><canvas id="cv" width="630" height="630"></canvas></div>
<div id="info">Bots explore with depth-first Tremaux rules, one cell per tick, backtracking from dead branches. Timer freezes when the last bot reaches the red exit.</div>
<script>
(function(){
"use strict";
var ROWS=21, COLS=21;
var canvas=document.getElementById('cv');
var ctx=canvas.getContext('2d');
var completedEl=document.getElementById('completed');
var timerEl=document.getElementById('timer');
var resetBtn=document.getElementById('reset');

function mulberry32(a){
  return function(){
    a|=0; a=a+0x6D2B79F5|0;
    var t=Math.imul(a^a>>>15,1|a);
    t=t+Math.imul(t^t>>>7,61|t)^t;
    return ((t^t>>>14)>>>0)/4294967296;
  };
}

var DIRS=[
  {k:'n',dr:-1,dc:0},
  {k:'e',dr:0,dc:1},
  {k:'s',dr:1,dc:0},
  {k:'w',dr:0,dc:-1}
];

function generateWalls(rows,cols,rng){
  var walls=[],vis=[],r,c;
  for(r=0;r<rows;r++){walls.push([]);vis.push([]);for(c=0;c<cols;c++){walls[r].push({n:true,e:true,s:true,w:true});vis[r].push(false);}}
  var stack=[{r:0,c:0}];vis[0][0]=true;
  while(stack.length>0){
    var cur=stack[stack.length-1];
    var opts=[];
    if(cur.r>0&&!vis[cur.r-1][cur.c])opts.push('n');
    if(cur.c<cols-1&&!vis[cur.r][cur.c+1])opts.push('e');
    if(cur.r<rows-1&&!vis[cur.r+1][cur.c])opts.push('s');
    if(cur.c>0&&!vis[cur.r][cur.c-1])opts.push('w');
    if(opts.length===0){stack.pop();}
    else{
      var d=opts[Math.floor(rng()*opts.length)];
      var nr=cur.r,nc=cur.c;
      if(d==='n'){walls[cur.r][cur.c].n=false;nr--;walls[nr][nc].s=false;}
      else if(d==='e'){walls[cur.r][cur.c].e=false;nc++;walls[nr][nc].w=false;}
      else if(d==='s'){walls[cur.r][cur.c].s=false;nr++;walls[nr][nc].n=false;}
      else{ walls[cur.r][cur.c].w=false;nc--;walls[nr][nc].e=false;}
      vis[nr][nc]=true;
      stack.push({r:nr,c:nc});
    }
  }
  return walls;
}

function shuffledPref(rng){
  var idx=[0,1,2,3];
  for(var i=3;i>0;i--){var j=Math.floor(rng()*(i+1));var t=idx[i];idx[i]=idx[j];idx[j]=t;}
  return [DIRS[idx[0]],DIRS[idx[1]],DIRS[idx[2]],DIRS[idx[3]]];
}

var state=null;

function buildState(seed){
  var mazeRng=mulberry32(seed|0);
  var wallsGrid=generateWalls(ROWS,COLS,mazeRng);
  var spawn={r:0,c:0};
  var exit={r:ROWS-1,c:COLS-1};
  var botRng=mulberry32((seed^0x5f3759df)|0);
  var bots=[];
  for(var i=0;i<24;i++){
    var pref=shuffledPref(botRng);
    var col='hsl('+Math.floor(i*360/24)+',85%,45%)';
    var b={
      r:spawn.r,c:spawn.c,
      path:[{r:spawn.r,c:spawn.c}],
      deadEnds:[],
      finishTick:null,
      pref:pref,
      color:col,
      stack:[{r:spawn.r,c:spawn.c}],
      visitedSet:{},
      deadSet:{},
      _vIdx:0,_vT:0
    };
    b.visitedSet[spawn.r+','+spawn.c]=1;
    bots.push(b);
  }
  // extra decorrelation: shuffle again per bot with own stream so orders differ strongly
  // (already done via sequential rng, deterministic)
  state={rows:ROWS,cols:COLS,wallsGrid:wallsGrid,spawn:spawn,exit:exit,bots:bots,elapsed:0,seed:seed};
}

function allDone(){
  for(var i=0;i<state.bots.length;i++)if(state.bots[i].finishTick===null)return false;
  return true;
}

function tickOnce(){
  if(allDone())return false;
  state.elapsed++;
  var exR=state.exit.r, exC=state.exit.c;
  for(var bi=0;bi<state.bots.length;bi++){
    var bot=state.bots[bi];
    if(bot.finishTick!==null)continue;
    if(bot.r===exR&&bot.c===exC){bot.finishTick=state.elapsed;continue;}
    var curW=state.wallsGrid[bot.r][bot.c];
    var found=null;
    for(var pi=0;pi<bot.pref.length;pi++){
      var d=bot.pref[pi];
      if(curW[d.k])continue;
      var nr=bot.r+d.dr,nc=bot.c+d.dc;
      if(nr<0||nr>=state.rows||nc<0||nc>=state.cols)continue;
      var key=nr+','+nc;
      if(bot.visitedSet[key])continue;
      found={r:nr,c:nc};
      break;
    }
    if(found){
      bot.r=found.r;bot.c=found.c;
      bot.visitedSet[found.r+','+found.c]=1;
      bot.stack.push({r:found.r,c:found.c});
      bot.path.push({r:found.r,c:found.c});
      if(found.r===exR&&found.c===exC)bot.finishTick=state.elapsed;
    }else{
      var ck=bot.r+','+bot.c;
      if(!(bot.r===exR&&bot.c===exC)){
        if(!bot.deadSet[ck]){bot.deadSet[ck]=1;bot.deadEnds.push({r:bot.r,c:bot.c});}
      }
      if(bot.stack.length>1){
        bot.stack.pop();
        var par=bot.stack[bot.stack.length-1];
        bot.r=par.r;bot.c=par.c;
        bot.path.push({r:bot.r,c:bot.c});
        if(bot.r===exR&&bot.c===exC)bot.finishTick=state.elapsed;
      }
    }
  }
  return true;
}

function updateHUD(){
  var done=0;
  for(var i=0;i<state.bots.length;i++)if(state.bots[i].finishTick!==null)done++;
  completedEl.textContent=done+'/24';
  timerEl.textContent=String(state.elapsed);
}

function draw(){
  var rows=state.rows,cols=state.cols;
  var cw=canvas.width/cols, ch=canvas.height/rows;
  ctx.fillStyle='#ffffff';
  ctx.fillRect(0,0,canvas.width,canvas.height);
  // spawn / exit highlights
  ctx.fillStyle='#c8f5c8';
  ctx.fillRect(state.spawn.c*cw,state.spawn.r*ch,cw,ch);
  ctx.fillStyle='#ffcdd2';
  ctx.fillRect(state.exit.c*cw,state.exit.r*ch,cw,ch);
  ctx.fillStyle='#2e7d32';
  ctx.font='bold '+Math.floor(Math.min(cw,ch)*0.45)+'px sans-serif';
  ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.fillText('S',(state.spawn.c+0.5)*cw,(state.spawn.r+0.5)*ch);
  ctx.fillStyle='#c62828';
  ctx.fillText('E',(state.exit.c+0.5)*cw,(state.exit.r+0.5)*ch);
  // walls
  ctx.strokeStyle='#000';
  ctx.lineWidth=3;
  ctx.lineCap='square';
  ctx.beginPath();
  for(var r=0;r<rows;r++){
    for(var c=0;c<cols;c++){
      var w=state.wallsGrid[r][c];
      var x=c*cw,y=r*ch;
      if(w.n){ctx.moveTo(x,y);ctx.lineTo(x+cw,y);}
      if(w.s){ctx.moveTo(x,y+ch);ctx.lineTo(x+cw,y+ch);}
      if(w.w){ctx.moveTo(x,y);ctx.lineTo(x,y+ch);}
      if(w.e){ctx.moveTo(x+cw,y);ctx.lineTo(x+cw,y+ch);}
    }
  }
  ctx.stroke();
  // bots (smooth interpolated, centered)
  for(var i=0;i<state.bots.length;i++){
    var b=state.bots[i];
    var idx=b._vIdx;
    if(idx<0)idx=0;
    if(idx>=b.path.length)idx=b.path.length-1;
    var cur=b.path[idx];
    var nxt=b.path[Math.min(idx+1,b.path.length-1)];
    var t=b._vT;
    if(idx>=b.path.length-1)t=0;
    var fr=cur.r+(nxt.r-cur.r)*t;
    var fc=cur.c+(nxt.c-cur.c)*t;
    var px=(fc+0.5)*cw, py=(fr+0.5)*ch;
    var rad=Math.min(cw,ch)*0.30;
    ctx.beginPath();
    ctx.arc(px,py,rad,0,Math.PI*2);
    ctx.fillStyle=b.color;
    ctx.fill();
    ctx.lineWidth=2;
    ctx.strokeStyle='#000';
    ctx.stroke();
    ctx.fillStyle='rgba(255,255,255,0.85)';
    ctx.beginPath();
    ctx.arc(px-rad*0.3,py-rad*0.3,rad*0.28,0,Math.PI*2);
    ctx.fill();
  }
}

var lastT=performance.now();
function frame(now){
  var dt=(now-lastT)/1000;lastT=now;
  if(dt>0.05)dt=0.05;
  if(dt<0)dt=0;
  for(var i=0;i<state.bots.length;i++){
    var b=state.bots[i];
    if(b._vIdx>=b.path.length){b._vIdx=Math.max(0,b.path.length-1);b._vT=0;}
    var lag=b.path.length-1-b._vIdx;
    if(lag>0){
      var speed=lag>40?lag*3:(lag>15?30:9);
      b._vT+=dt*speed;
      while(b._vT>=1&&b._vIdx<b.path.length-1){b._vT-=1;b._vIdx++;}
      if(b._vIdx>=b.path.length-1){b._vIdx=b.path.length-1;b._vT=0;}
    }
  }
  draw();
  requestAnimationFrame(frame);
}

window.game={};
Object.defineProperty(window.game,'elapsed',{get:function(){return state.elapsed;}});
Object.defineProperty(window.game,'size',{get:function(){return {rows:state.rows,cols:state.cols};}});
Object.defineProperty(window.game,'spawn',{get:function(){return {r:state.spawn.r,c:state.spawn.c};}});
Object.defineProperty(window.game,'exit',{get:function(){return {r:state.exit.r,c:state.exit.c};}});
Object.defineProperty(window.game,'bots',{get:function(){return state.bots;}});
window.game.walls=function(r,c){var w=state.wallsGrid[r][c];return {n:w.n,e:w.e,s:w.s,w:w.w};};
window.game.tick=function(n){
  if(n===undefined||n===null)n=1;
  n=Math.floor(Number(n));
  if(!(n>0))return;
  for(var k=0;k<n;k++){
    if(allDone())break;
    tickOnce();
  }
  updateHUD();
};
window.game.reset=function(seed){
  var s;
  if(typeof seed==='number'&&isFinite(seed))s=Math.floor(seed);
  else s=Math.floor(Math.random()*1000000000);
  buildState(s);
  updateHUD();
  draw();
};

resetBtn.addEventListener('click',function(){window.game.reset();});

buildState(Math.floor(Math.random()*1000000000));
updateHUD();
draw();
requestAnimationFrame(frame);
setInterval(function(){
  if(!allDone()){window.game.tick(1);}
},70);
})();
</script>
</body>
</html>
